// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    Bank bank;

    function setUp() public {
        c = new ModifierEntrancy();
        bank = new Bank();
    }

    function testFuzz_property(uint256 seed) public {
        vm.assume(seed < type(uint256).max);
        // drive airdrop from the bank so supportsToken check passes; fresh caller has zero balance
        vm.prank(address(bank));
        bool ok;
        try c.airDrop() { ok = true; } catch { ok = false; }
        assertTrue(ok && c.tokenBalance(address(bank)) == 20);
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
